// The reTerminal E-series' own layout (E1001, E1002, E1003, E1004): a status
// bar along the edge the keys are on, with the signal, the battery and the time
// the picture was drawn, and under each key what a press does and, smaller,
// what holding it does. It draws
// when the scene draws and never on its own, so an e-paper panel refreshes no
// more often for it. Over the scene list (both arrows held, in the maps the
// boards come with) the bar says what each key does there, and the date where
// the scene's name was. On the E1003, whose glass is touch, the bar's parts
// are buttons too (for a finger: the keys' ring passes them by). A scene that
// asks for the whole glass (a reader) gets it. What it shows, and what the
// green key does for it, are the layout's settings.
// The bar's two colours: black on white, or white on black (the "Colours"
// setting, put in place at the start of each render).
let INK = '#000000'
let PAPER = '#ffffff'
const WHITE = '#ffffff'
// Spectra 6 inks as the panel shows them (dither.nim's measured table), so a
// colour panel draws them solid.
const GREEN = '#2a5531'
const RED = '#6b1119'

const pad = (n) => String(n).padStart(2, '0')

// The layout's settings as it uses them. A switch comes as true / false or as
// its text, and is on until it is turned off.
const on = (value) => value !== false && value !== 'false'
const SIZES = { small: 0.85, normal: 1, large: 1.2 }
function settingsOf(state) {
  return {
    refresh: on(state.refresh),
    holds: on(state.holds),
    tip: on(state.tip),
    signal: on(state.signal),
    battery: on(state.battery),
    clock: state.clock === '12' || state.clock === 'off' ? state.clock : '24',
    dark: state.colors === 'dark',
    scale: SIZES[state.size] || 1,
  }
}
// The time the picture was drawn, as the "Time" setting says; null for none.
function timeText(now, format) {
  if (format === 'off') return null
  if (format === '12') return `${now.getHours() % 12 || 12}:${pad(now.getMinutes())} ${now.getHours() < 12 ? 'am' : 'pm'}`
  return `${pad(now.getHours())}:${pad(now.getMinutes())}`
}
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December']
// The date, as long as `letters` lets it be: "Friday, 27 November" down to
// "Fri 27 Nov".
function dateText(now, letters) {
  const day = DAYS[now.getDay()]
  const month = MONTHS[now.getMonth()]
  const forms = [`${day}, ${now.getDate()} ${month}`, `${day} ${now.getDate()} ${month.slice(0, 3)}`,
    `${day.slice(0, 3)} ${now.getDate()} ${month.slice(0, 3)}`]
  return forms.find((form) => form.length <= letters) || forms[forms.length - 1]
}

// A text's size where it has `room` along it: `max`, smaller for a long one,
// never under `min`. A letter is about `em` of the size (Ubuntu: bold 0.56,
// regular 0.5).
const fitSize = (words, room, max, min, em) =>
  Math.round(Math.max(min, Math.min(max, words ? room / (words.length * em) : max)))

// A tap on a part of the bar, which the E1003's glass takes: pressed on it and
// let go on it. Pointer handlers, not an onClick: an element with an onClick
// is a stop of the keys' ring (docs/jsx-ui.md "Keys"), and the bar's parts
// would take the arrows from every scene with nothing to press, whose Prev and
// Next are its back and forward. The keys have the same places on their holds
// (the caps say which).
let tapping = ''
const tap = (part, act) => ({
  onPointerDown: () => {
    tapping = part
    return false
  },
  onPointerUp: (e) => {
    const on = tapping === part && !(e.localX < 0 || e.localY < 0 || e.localX >= e.width || e.localY >= e.height)
    tapping = ''
    if (on) act()
    return false
  },
})

// Where the keys are on each model, the panel unturned: along an edge, each
// as a share of its length from the start (Seeed's drawings). The E1001,
// E1002 and E1003 have them on top, right of centre; seen from the front the
// one labelled RIGHT is the left one and LEFT the middle one (their arrows are
// printed on the back), the green REFRESH key last. The E1004's panel is
// upright (1200x1600), its touch keys under the picture, REFRESH, LEFT and
// RIGHT from the left; hung landscape they are on a side. Only the E1001-E1003's
// REFRESH key is green; the E1004's touch keys are printed alike.
const TOP_KEYS = [
  { label: 'RIGHT', at: 0.56 },
  { label: 'LEFT', at: 0.615 },
  { label: 'REFRESH', at: 0.685 },
]
const MODELS = {
  e1001: { name: 'E1001', edge: 'top', keys: TOP_KEYS, touch: false, green: true },
  e1002: { name: 'E1002', edge: 'top', keys: TOP_KEYS, touch: false, green: true },
  e1003: { name: 'E1003', edge: 'top', keys: TOP_KEYS, touch: true, green: true },
  e1004: {
    name: 'E1004',
    edge: 'bottom',
    keys: [
      { label: 'REFRESH', at: 0.41 },
      { label: 'LEFT', at: 0.5 },
      { label: 'RIGHT', at: 0.59 },
    ],
    touch: false,
    green: false,
  },
}
// What the planes give each model when a frame has no map to tell (the
// preview): each preset's BOARD_KEYS[...].eventMap, copied from
// frontend/src/generated/boardKeys.gen.ts (frameos/tools/generate_board_keys.py,
// docs/buttons.md), since a scene imports nothing of the repository's. The
// arrows held walk the scenes (by role, so they turn with the frame), both
// arrows together are Back and held the scene list, and the green key held
// talks on the three with a microphone; the E1004's REFRESH held is the list.
const TALK = { event: 'button', match: { label: 'REFRESH', action: 'longPress' }, emit: 'voiceChat', as: {} }
const LIST = { event: 'button', match: { label: 'REFRESH', action: 'longPress' }, emit: 'sceneSwitcher', as: {} }
const ARROWS = [
  { event: 'button', match: { role: 'prev', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'prev' } },
  { event: 'button', match: { role: 'next', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'next' } },
  { event: 'button', match: { role: 'back', action: 'press' }, emit: 'back', as: {} },
  { event: 'button', match: { role: 'back', action: 'longPress' }, emit: 'sceneSwitcher', as: {} },
]
const SWIPES = [
  { event: 'edgeSwipe', match: { edge: 'right' }, emit: 'forward', as: {} },
  { event: 'edgeSwipe', match: { edge: 'left' }, emit: 'back', as: {} },
  { event: 'edgeSwipe', match: { edge: 'bottom' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'top' }, emit: 'sceneSettings', as: {} },
]
const DEFAULT_MAPS = {
  e1001: [TALK, ...ARROWS],
  e1002: [TALK, ...ARROWS],
  e1003: [TALK, ...ARROWS, ...SWIPES],
  e1004: [LIST, ...ARROWS],
}
// The Action key (docs/buttons.md), REFRESH on the board. The layout listens
// to it: a press, where the frame's map leaves the press to the scene, draws
// the picture again.
const ACTION_KEY = 'REFRESH'
// How long a key is held before it is a hold (buttons.longPressMs).
const HOLD_MS = 1000

// A key's role as the frame hears it (docs/buttons.md): REFRESH is the Action
// key, `primary`, and an arrow is `next` where it points to the right or the
// bottom of the picture as the frame hangs, else `prev` (input_state.nim
// `facing`; a flip, which a layout is not told, aside). Where an arrow points
// is where it sits on the panel unturned, seen from the front (the presets'
// EMBEDDED_BOARD_KEYS): on the E1001-E1003 the arrows are printed for someone
// behind the frame, so RIGHT is the left one and LEFT, beside the green key,
// the next; the E1004's are printed on its front.
const POINTS = { LEFT: [1, 0], RIGHT: [-1, 0] }
const E1004_POINTS = { LEFT: [-1, 0], RIGHT: [1, 0] }
function roleOf(label, rotate, model) {
  const p = (model === 'e1004' ? E1004_POINTS : POINTS)[label]
  if (!p) return 'primary'
  const [x, y] = { 90: [p[1], -p[0]], 180: [-p[0], -p[1]], 270: [-p[1], p[0]] }[rotate] || p
  return (Math.abs(x) >= Math.abs(y) ? x > 0 : y > 0) ? 'next' : 'prev'
}
const turnOf = (frame) => ((Number(frame.rotate) || 0) % 360 + 360) % 360

const ICON = {
  apps: 'M4,4H10V10H4V4M14,4H20V10H14V4M4,14H10V20H4V14M14,14H20V20H14V14Z',
  cog: 'M12,15.5A3.5,3.5 0 0,1 8.5,12A3.5,3.5 0 0,1 12,8.5A3.5,3.5 0 0,1 15.5,12A3.5,3.5 0 0,1 12,15.5M19.43,12.97C19.47,12.65 19.5,12.33 19.5,12C19.5,11.67 19.47,11.34 19.43,11L21.54,9.37C21.73,9.22 21.78,8.95 21.66,8.73L19.66,5.27C19.54,5.05 19.27,4.96 19.05,5.05L16.56,6.05C16.04,5.66 15.5,5.32 14.87,5.07L14.5,2.42C14.46,2.18 14.25,2 14,2H10C9.75,2 9.54,2.18 9.5,2.42L9.13,5.07C8.5,5.32 7.96,5.66 7.44,6.05L4.95,5.05C4.73,4.96 4.46,5.05 4.34,5.27L2.34,8.73C2.21,8.95 2.27,9.22 2.46,9.37L4.57,11C4.53,11.34 4.5,11.67 4.5,12C4.5,12.33 4.53,12.65 4.57,12.97L2.46,14.63C2.27,14.78 2.21,15.05 2.34,15.27L4.34,18.73C4.46,18.95 4.73,19.03 4.95,18.95L7.44,17.94C7.96,18.34 8.5,18.68 9.13,18.93L9.5,21.58C9.54,21.82 9.75,22 10,22H14C14.25,22 14.46,21.82 14.5,21.58L14.87,18.93C15.5,18.67 16.04,18.34 16.56,17.94L19.05,18.95C19.27,19.03 19.54,18.95 19.66,18.73L21.66,15.27C21.78,15.05 21.73,14.78 21.54,14.63L19.43,12.97Z',
}

const Icon = ({ d, size }) => (
  <svg viewBox="0 0 24 24" width={size} height={size}>
    <path d={d} fill="currentColor" />
  </svg>
)

// The model: the owner's choice, else the panel's size and colours.
function modelOf(frame, setting) {
  if (MODELS[setting]) return setting
  const scale = Number(frame.scale) || 1
  const long = Math.round(Math.max(frame.width, frame.height) * scale)
  if (long >= 1800) return 'e1003'
  if (long >= 1500) return 'e1004'
  return frame.color === false ? 'e1001' : 'e1002'
}

// The side of the picture the keys are on: the panel's edge with them, as
// the frame's rotation turns it. The E1001-E1003's top edge goes to the left
// at 90, the bottom at 180 and the right at 270; the E1004's bottom edge to
// the right at 90, the top at 180 and the left at 270 (hung landscape, the
// keys are beside the picture). The owner's "Keys" setting wins.
const TURNED = {
  top: { 0: 'top', 90: 'left', 180: 'bottom', 270: 'right' },
  bottom: { 0: 'bottom', 90: 'right', 180: 'top', 270: 'left' },
}
function keySide(model, frame, setting) {
  if (['top', 'bottom', 'left', 'right'].includes(setting)) return setting
  const edge = MODELS[model].edge
  return TURNED[edge][turnOf(frame)] || edge
}
// A key's place along that side, from its top or its left: the keys' order
// runs left to right on the unturned panel, and backwards where a turn has
// brought that edge's left end to the bottom or the right.
const along = (model, side, at) => {
  const ahead = MODELS[model].edge === 'top' ? side === 'top' || side === 'right' : side === 'bottom' || side === 'left'
  return ahead ? at : 1 - at
}

// A rule's emit in a word. Under an arrow that already says which way, a scene
// change is just "Scene".
function said(rule) {
  switch (rule.emit) {
    case 'setCurrentScene': return 'Scene'
    case 'voiceChat': return 'Talk'
    case 'sceneSwitcher': return 'Scenes'
    case 'sceneSettings': return 'Settings'
    case 'toggleScreen': return 'Screen'
    case 'render': return 'Refresh'
    case 'back': return 'Back'
    case 'forward': return 'Forward'
    default: return rule.emit ? String(rule.emit) : null
  }
}
// The rule of the frame's map that takes a press (`action`: press, longPress),
// the first whose every match value the press carries, as the dispatcher reads
// them (event_map.nim): a rule names a key by its label or by its role.
function ruleFor(map, press) {
  return map.find((rule) => rule.event === 'button' && rule.match &&
    Object.keys(rule.match).every((key) => String(rule.match[key]) === String(press[key])))
}
const keyRule = (map, label, action, rotate, model) => ruleFor(map, { label, role: roleOf(label, rotate, model), action })
// Both arrows pressed together: the Back key of a board that has none, where
// the map binds a `back` by role (docs/buttons.md).
const bothRule = (map, action) => ruleFor(map, { label: 'LEFT+RIGHT', role: 'back', action })
const swipeRule = (map, edge) => map.find((rule) => rule.event === 'edgeSwipe' && rule.match && rule.match.edge === edge)
const mapOf = (frame, model) => (Array.isArray(frame.eventMap) ? frame.eventMap : DEFAULT_MAPS[model])
const listShows = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSwitcher')

// The green key's press draws the picture again, where the frame's map leaves
// the press to the scene and the owner has not turned it off. The layout hears
// the key's edges (`gpio`), never its `button`: a layout that listens for
// `button` makes every scene it wraps one that does, and such a scene's arrows
// are no longer its forward and back (docs/buttons.md). A press is the key let
// go before it is a hold, with no other key moving meanwhile (two keys are Back).
let pressing = false
let alone = true
export function onEvent(app, context) {
  const edge = context.payload || {}
  if (context.event !== 'gpio') return false
  if (edge.label !== ACTION_KEY) {
    if (pressing) alone = false
    return false
  }
  if (edge.action === 'down') {
    pressing = alone = true
    return false
  }
  const press = edge.action === 'up' && alone && !edge.claimed && !(Number(edge.durationMs) >= HOLD_MS)
  pressing = false
  alone = true
  if (!press || app.frame.systemScene || !settingsOf(app.state).refresh) return false
  const map = mapOf(app.frame, modelOf(app.frame, app.state.model))
  const taken = ['press', 'doublePress', 'triplePress'].some((action) => keyRule(map, ACTION_KEY, action, turnOf(app.frame)))
  if (!taken) frameos.dispatch('render')
  return false
}

function Signal({ rssi, u }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${Math.max(1, Math.round(u * 0.4))}px] h-[${Math.round(u * 3)}px]`}>
      {[0.3, 0.55, 0.8, 1].map((share, i) => (
        <div className={`w-[${Math.max(2, Math.round(u * 0.6))}px] h-[${Math.round(u * 3 * share)}px] ${i < level ? `bg-[${INK}]` : `border border-[${INK}]`}`} />
      ))}
    </div>
  )
}

// The battery: its level, and the percentage beside it, or under it in a
// narrow bar.
function Battery({ percent, u, color, stacked }) {
  if (typeof percent !== 'number') return null
  const low = percent <= 15
  const ink = low && color ? RED : INK
  const w = Math.round(u * 5)
  const h = Math.round(u * 2.6)
  const line = Math.max(1, Math.round(u * 0.3))
  const inner = Math.max(0, Math.round((w - 4 * line) * Math.min(100, Math.max(0, percent)) / 100))
  return (
    <div className={`flex ${stacked ? 'flex-col' : ''} items-center gap-[${line}px] text-[${ink}]`}>
      <div className="flex items-center">
      <div className={`flex items-center w-[${w}px] h-[${h}px] p-[${line}px] border-[${line}px] border-[${ink}] rounded-[${line * 2}px]`}>
        <div className={`h-full w-[${inner}px] bg-[${ink}]`} />
      </div>
      <div className={`w-[${line * 2}px] h-[${Math.round(h / 2.5)}px] bg-[${ink}]`} />
      </div>
      <span className={`${stacked ? '' : `pl-[${line * 2}px]`} font-semibold`}>{`${percent}%`}</span>
    </div>
  )
}

// Words turned to run along a bar on a side, `w` x `h`, read from the top on
// the right and from the bottom on the left. The UI lays text out level, so
// they are an <svg> of their own: `lines` ([text, size, weight, smallest])
// from the panel's edge in, each made smaller to fit along `h` (down to its
// smallest, where it has one) and cut to what fits.
function Turned({ w, h, side, lines }) {
  const turn = side === 'left' ? -90 : 90
  const shown = lines.filter((line) => line && line[0])
    .map(([text, size, weight, smallest]) =>
      [text, smallest ? fitSize(text, h, size, smallest, weight === 'normal' ? 0.5 : 0.56) : size, weight])
  const step = (size) => size * 1.2
  let at = -shown.reduce((sum, line) => sum + step(line[1]), 0) / 2
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>
      <g transform={`translate(${w / 2} ${h / 2}) rotate(${turn})`} fill="currentColor">
        {shown.map(([text, size, weight]) => {
          const y = at + step(size) / 2
          at += step(size)
          const room = Math.max(1, Math.floor(h / (size * (weight === 'normal' ? 0.5 : 0.56))))
          const cut = text.length > room ? `${text.slice(0, Math.max(1, room - 1))}…` : text
          return (
            <text x="0" y={y} font-size={size} font-weight={weight} text-anchor="middle" dominant-baseline="central">
              {cut}
            </text>
          )
        })}
      </g>
    </svg>
  )
}

// One key's cap, hanging from the edge beside the key: what a press does, and
// under it, smaller, what holding it does. The green key is green where the
// panel has the ink.
function Cap({ side, word, held, green, lit, w, h, wordSize, heldSize, gap }) {
  const corner = { top: 'rounded-b-[8px]', bottom: 'rounded-t-[8px]', left: 'rounded-r-[8px]', right: 'rounded-l-[8px]' }[side]
  const look = lit ? `bg-[${INK}] text-[${PAPER}]` : green ? `bg-[${GREEN}] text-[${WHITE}]` : `bg-[${PAPER}] text-[${INK}] border-2 border-[${INK}]`
  if (side === 'left' || side === 'right') {
    // On a side, the words turned along the bar, which stays narrow.
    return (
      <div className={`flex items-center justify-center w-full h-full ${corner} ${look}`}>
        <Turned w={w - 4} h={h - 4} side={side} lines={[[word, wordSize, 'bold'], [held, heldSize, '600']]} />
      </div>
    )
  }
  return (
    <div className={`flex flex-col items-center justify-center gap-[${gap}px] w-full h-full ${corner} ${look}`}>
      <span className={`text-[${wordSize}px] font-bold leading-none whitespace-nowrap`}>{word}</span>
      {held ? <span className={`text-[${heldSize}px] font-semibold leading-none whitespace-nowrap`}>{held}</span> : null}
    </div>
  )
}

// The caps along the edge, `length` long: each from halfway to the key before
// it to halfway to the one after, the outer ones as far again out, so the
// E1001's keys, 44 px apart on an 800 px panel, still have room for a word.
// Every cap's words one size, the largest at which each fits its cap with a
// little room either side (the E1003's Next, between keys 52 px apart, had
// none).
function caps(model, side, length, depth, u, list) {
  const across = side === 'left' || side === 'right'
  const placed = list.map((cap) => ({ ...cap, centre: along(model, side, cap.at) * length }))
    .sort((a, b) => a.centre - b.centre)
  const outer = u * 9
  const spans = placed.map((cap, i) => {
    const from = i > 0 ? (placed[i - 1].centre + cap.centre) / 2 : cap.centre - outer
    const to = i < placed.length - 1 ? (cap.centre + placed[i + 1].centre) / 2 : cap.centre + outer
    const start = Math.max(0, Math.round(from))
    return { cap, start, span: Math.min(length, Math.round(to)) - start }
  })
  // The room along a cap: its span less the gaps between caps, the border and
  // a margin either side.
  const roomIn = (span) => span - 8 - u * 1.6
  const wordSize = Math.min(...spans.map(({ cap, span }) => fitSize(cap.word, roomIn(span), u * 2.9, u * 2, 0.56)))
  const heldSize = Math.min(...spans.map(({ cap, span }) => fitSize(cap.held, roomIn(span), u * 2.1, u * 1.6, 0.52)))
  return spans.map(({ cap, start, span }) => {
    const place = across ? `top-[${start}px] left-0 w-full h-[${span}px]` : `left-[${start}px] top-0 h-full w-[${span}px]`
    return (
      <div className={`absolute ${place} ${across ? 'py-[2px]' : 'px-[2px]'}`}>
        <Cap side={side} word={cap.word} held={cap.held} green={cap.green} lit={cap.lit} w={depth} h={span - 4}
          wordSize={wordSize} heldSize={heldSize} gap={Math.round(u * 0.5)} />
      </div>
    )
  })
}

// Each key's cap (the small word, too narrow on the E1001 for "hold", is
// explained under the scene's name): what a press does (the frame's map, else the scene's own:
// the arrows step through what it shows, the green key draws it again) and
// what holding it does. Over the scene list a press moves and opens, and the
// arrows held move it a screenful. Where the owner turned the green key's press
// off, it goes to the scene alone; and the small words can be left off.
function capsFor(model, map, rotate, onList, colour, set) {
  return MODELS[model].keys.map((key) => {
    const action = key.label === ACTION_KEY
    const green = action && colour && MODELS[model].green
    const pressed = keyRule(map, key.label, 'press', rotate, model)
    const held = keyRule(map, key.label, 'longPress', rotate, model)
    const arrow = roleOf(key.label, rotate, model) === 'next' ? 'Next' : 'Prev'
    if (onList) {
      // Held, the green key talks where the frame's map says so, and else
      // closes the list (the list's own rule for a long press left free, and
      // the list asked for again while it shows: the E1004's).
      const holds = !set.holds ? null : action ? (held && held.emit !== 'sceneSwitcher' ? said(held) : 'Close') : held ? 'Page' : null
      return { at: key.at, word: action ? 'Open' : arrow, held: holds, green, lit: action && !green }
    }
    const word = pressed ? said(pressed) : action ? (set.refresh ? 'Refresh' : 'To scene') : arrow
    return { at: key.at, word, held: set.holds && held ? said(held) : null, green }
  })
}

// Both arrows together, in words, where the frame's map makes them the Back
// key: "both arrows: Back", "held: Scenes". The hold is left out where a cap's
// small word already says it (the E1004's Refresh held: Scenes).
function together(model, map, rotate, capsHold) {
  const pressed = bothRule(map, 'press')
  const held = bothRule(map, 'longPress')
  const capSays = held && capsHold && MODELS[model].keys.some((key) => {
    const rule = keyRule(map, key.label, 'longPress', rotate, model)
    return rule && rule.emit === held.emit
  })
  const words = []
  if (pressed) words.push(`both arrows: ${said(pressed)}`)
  if (held && !capSays) words.push(`${pressed ? 'held' : 'both arrows held'}: ${said(held)}`)
  return words
}

// The help's groups of phrases, in the order they are told: that the caps'
// small word is the hold, and how to reach the scene list (the glass), or Back
// and the list (both arrows together, where the frame's map has them); over
// the list, how to move through it.
function tipGroups({ model, map, rotate, onList, touch, capsHold, held, set }) {
  if (!set.tip) return []
  return [
    held ? ['Small word: hold'] : [],
    onList ? hints(model) : touch ? [swipeRule(map, 'bottom') ? 'swipe up: all scenes' : 'tap: all scenes']
      : together(model, map, rotate, capsHold),
  ].filter((group) => group.length)
}
// The groups told on one line of `letters`, each whole or not at all
// ("Small word: hold · both arrows: Back, held: Scenes"), and the ones left
// over for another place.
function tipLine(groups, letters) {
  let line = ''
  const rest = []
  for (const group of groups) {
    const part = group.join(', ')
    const longer = line ? `${line} · ${part}` : part
    if (longer.length <= letters) line = longer
    else rest.push(group)
  }
  return { line, rest }
}
// What is left over, a phrase a line, at most `most` lines `room` long, each
// whole, at `size` or as much smaller as the longest needs (down to
// `smallest`); a group that does not fit is left out.
function restLines(groups, room, most, size, smallest) {
  const letters = room / (smallest * 0.5)
  const lines = []
  for (const group of groups) {
    const phrases = group.every((phrase) => phrase.length <= letters) ? group : []
    if (lines.length + phrases.length <= most) lines.push(...phrases)
  }
  const longest = lines.reduce((a, b) => (b.length > a.length ? b : a), '')
  return { lines, size: fitSize(longest, room, size, smallest, 0.5) }
}

// Over the scene list, how to move through it.
const hints = (model) => (MODELS[model].touch ? ['tap one', 'or use the keys']
  : ['arrows move', MODELS[model].green ? 'green opens' : 'Refresh opens'])

const sum = (list) => list.reduce((a, b) => a + b, 0)

function Bar({ app, model, side, W, H, u, onList, set }) {
  const frame = app.frame
  const touch = MODELS[model].touch
  const colour = frame.color !== false
  const map = mapOf(frame, model)
  const rotate = turnOf(frame)
  const across = side === 'left' || side === 'right'
  // Two lines of words deep, along the top or the bottom, and on a side, where
  // the words are turned to run along it.
  const size = Math.round(u * (across ? 6.5 : 8))
  const now = new Date()
  const showKeys = app.state.bar !== 'quiet'
  const text = Math.round(u * 3.1)
  const small = Math.round(u * 2.3)
  // A long name is made smaller to fit, down to this, and then cut.
  const smallest = Math.round(u * 2.4)
  const keyZone = MODELS[model].keys.map((key) => along(model, side, key.at))
  const zoneStart = Math.min(...keyZone)
  const zoneEnd = Math.max(...keyZone)
  // Room before and after the keys' caps, for the name, the help and the status.
  const length = across ? H : W
  const before = Math.max(0, Math.round(zoneStart * length - u * 11))
  const after = Math.max(0, Math.round(length - zoneEnd * length - u * 11))
  // The help (tipGroups) goes under the name, each group where the line has
  // room for it whole, a letter about half the text's size, never cut; what
  // does not fit there goes to the other side of the keys, a phrase a line,
  // where that has room (the E1004's keys, in the middle, leave too little
  // under the name for the arrows').
  const capsHold = showKeys && set.holds
  const held = capsHold && MODELS[model].keys.some((key) => keyRule(map, key.label, 'longPress', rotate, model))
  const groups = tipGroups({ model, map, rotate, onList, touch, capsHold, held, set })
  const time = timeText(now, set.clock)
  const rssi = set.signal && typeof frame.wifiRssi === 'number'
  const battery = set.battery && typeof frame.batteryPercent === 'number'
  const gearShown = touch && !onList
  // The scene's name; over the scene list, which titles itself, the date, as
  // long as there is room for.
  const named = (letters) => (onList ? dateText(now, letters) : app.state.title || frame.sceneName || '')
  const toList = touch ? tap('name', () => frameos.dispatch('sceneSwitcher')) : {}
  const toFrame = touch ? tap('status', () => frameos.dispatch('sceneSettings', { page: 'frame' })) : {}
  const gear = gearShown ? (
    <div className={`flex items-center justify-center w-[${Math.round(u * 5.5)}px] h-[${Math.round(u * 5.5)}px] rounded-full border-2 border-[${INK}] shrink-0`}
      {...tap('gear', () => frameos.dispatch('sceneSettings'))}>
      <Icon d={ICON.cog} size={Math.round(u * 3.6)} />
    </div>
  ) : null
  const edgeLine = { top: 'border-b-2', bottom: 'border-t-2', left: 'border-r-2', right: 'border-l-2' }[side]
  if (across) {
    // A narrow strip: the caps beside the keys, the gear, the signal, the
    // battery (its percentage under it) and the time at its far end, and the
    // name and the help turned along it in the longer of the two stretches
    // the caps leave (before them, or after them down to the gear), what help
    // is left over in the other.
    const status = [rssi ? Math.round(u * 2.4) : 0, battery ? Math.round(u * 5.6) : 0,
      time ? Math.round(text * 0.56 * time.length + u * 2) : 0].filter(Boolean)
    const stack = [gearShown ? Math.round(u * 5.5) : 0, status.length ? sum(status) + u * 1.5 * (status.length - 1) : 0]
      .filter(Boolean)
    const tail = u * 2 + sum(stack) + u * 1.5 * Math.max(0, stack.length - 1)
    const afterAt = Math.round(zoneEnd * H + u * 11)
    const first = { at: Math.round(u * 2), room: Math.round(showKeys ? before - u * 2 : H / 2 - u * 2) }
    const second = { at: afterAt, room: showKeys ? Math.round(H - tail - u - afterAt) : 0 }
    const [place, other] = second.room > first.room ? [second, first] : [first, second]
    const { line, rest } = tipLine(groups, place.room / (small * 0.5))
    const more = restLines(other.room > u * 6 ? rest : [], other.room, 2, small, Math.round(u * 1.8))
    const words = (where, lines, handlers) => (
      <div className={`absolute top-[${where.at}px] left-0 w-full h-[${where.room}px] flex items-center justify-center`} {...handlers}>
        <Turned w={size} h={where.room} side={side} lines={lines} />
      </div>
    )
    return (
      <div className={`relative flex flex-col items-center justify-end gap-[${Math.round(u * 1.5)}px] w-[${size}px] h-full pb-[${Math.round(u * 2)}px] shrink-0 bg-[${PAPER}] text-[${INK}] text-[${small}px] ${edgeLine} border-[${INK}]`}>
        {place.room > u * 6
          ? words(place, [[named(place.room / (text * 0.56)), text, 'bold', smallest], [line, small, 'normal']], toList)
          : null}
        {more.lines.length ? words(other, more.lines.map((phrase) => [phrase, more.size, 'normal'])) : null}
        {showKeys ? caps(model, side, H, size, u, capsFor(model, map, rotate, onList, colour, set)) : null}
        {gear}
        {rssi || battery || time ? (
          <div className={`flex flex-col items-center gap-[${Math.round(u * 1.5)}px] shrink-0`} {...toFrame}>
            {rssi ? <Signal rssi={frame.wifiRssi} u={u * 0.8} /> : null}
            {battery ? <Battery percent={frame.batteryPercent} u={u * 0.8} color={colour} stacked /> : null}
            {time ? <Turned w={size} h={Math.round(text * 0.56 * time.length + u * 2)} side={side} lines={[[time, text, 'bold']]} /> : null}
          </div>
        ) : null}
      </div>
    )
  }
  // Along the top or the bottom: the name and the help before the keys' caps,
  // the status after them, and what help is left over beside the status.
  const nameRoom = (showKeys ? before : W / 2) - u * (4 + (touch ? 4.4 : 0) + (gearShown ? 7.5 : 0))
  const name = named(nameRoom / (text * 0.56))
  const { line, rest } = tipLine(groups, nameRoom / (small * 0.5))
  const statusLong = [rssi ? u * 3.6 : 0, battery ? u * 6.2 + text * 0.56 * 4 : 0, time ? text * 0.5 * time.length : 0]
    .filter(Boolean)
  const restRoom = showKeys ? after - u * 6 - sum(statusLong) - u * 2 * Math.max(0, statusLong.length - 1) : 0
  const more = restLines(restRoom > u * 8 ? rest : [], restRoom, 2, small, Math.round(u * 1.8))
  const status = rssi || battery || time ? (
    <div className={`flex flex-row items-center gap-[${Math.round(u * 2)}px] shrink-0`} {...toFrame}>
      {rssi ? <Signal rssi={frame.wifiRssi} u={u} /> : null}
      {battery ? <Battery percent={frame.batteryPercent} u={u} color={colour} /> : null}
      {time ? <span className="whitespace-nowrap font-semibold">{time}</span> : null}
    </div>
  ) : null
  return (
    <div className={`relative flex items-center h-[${size}px] w-full shrink-0 bg-[${PAPER}] text-[${INK}] text-[${text}px] ${edgeLine} border-[${INK}]`}>
      {showKeys ? caps(model, side, W, size, u, capsFor(model, map, rotate, onList, colour, set)) : null}
      <div className={`flex items-center gap-[${Math.round(u * 2)}px] h-full pl-[${Math.round(u * 3)}px] ${showKeys ? `w-[${before}px]` : 'flex-1'} min-w-0`}>
        <div className={`flex flex-1 items-center gap-[${Math.round(u)}px] min-w-0`} {...toList}>
          {touch ? <Icon d={ICON.apps} size={Math.round(u * 3.4)} /> : null}
          <div className="flex flex-col min-w-0">
            <span className={`truncate text-[${fitSize(name, nameRoom, text, smallest, 0.56)}px] font-bold leading-none`}>{name}</span>
            {line ? <span className={`truncate text-[${small}px] leading-none pt-[${Math.round(u * 0.4)}px]`}>{line}</span> : null}
          </div>
        </div>
        {gear}
      </div>
      {showKeys ? <div className="flex-1" /> : null}
      <div className={`flex items-center justify-end gap-[${Math.round(u * 2)}px] h-full pr-[${Math.round(u * 3)}px] ${showKeys ? `w-[${after}px]` : ''} min-w-0`}>
        {more.lines.length ? (
          <div className={`flex flex-col flex-1 min-w-0 pl-[${Math.round(u)}px] text-[${more.size}px] leading-tight`}>
            {more.lines.map((phrase) => <span className="whitespace-nowrap">{phrase}</span>)}
          </div>
        ) : null}
        {status}
      </div>
    </div>
  )
}

export function get(app) {
  const frame = app.frame
  const W = frame.width
  const H = frame.height
  const set = settingsOf(app.state)
  INK = set.dark ? '#ffffff' : '#000000'
  PAPER = set.dark ? '#000000' : '#ffffff'
  // One unit, a hundredth of the shorter edge, times the "Text size".
  const u = Math.min(W, H) / 100 * set.scale
  const model = modelOf(frame, app.state.model)
  const side = keySide(model, frame, app.state.keys)
  const onList = listShows(frame)
  // The settings get the whole panel, and so does a scene while its keyboard
  // is up (the E1003's glass): the keyboard reaches across the bar. So does
  // one that asks for it (a reader's "Full screen": app.frame.fullScreen).
  if ((frame.systemScene && !onList) || frame.typing || (frame.fullScreen && !onList)) return <yield />
  if (app.state.bar === 'off' && !onList) return <yield />
  const across = side === 'left' || side === 'right'
  const bar = <Bar app={app} model={model} side={side} W={W} H={H} u={u} onList={onList} set={set} />
  const first = side === 'top' || side === 'left'
  const body = (
    <div className="flex flex-col flex-1 min-w-0 min-h-0">
      <yield />
    </div>
  )
  return (
    <div className={`flex ${across ? 'flex-row' : 'flex-col'} w-full h-full bg-[${PAPER}]`}>
      {first ? bar : null}
      {body}
      {first ? null : bar}
    </div>
  )
}
